// Logo: globo de diálogo con un brote
function logo(s = 48) {
  return `<svg width="${s}" height="${s}" viewBox="0 0 48 48" aria-hidden="true"><path d="M24 4C12.4 4 4 11.6 4 21.5c0 5.3 2.5 10 6.6 13.2L9 43l9.2-4.9c1.8.4 3.8.7 5.8.7 11.6 0 20-7.6 20-17.3S35.6 4 24 4z" fill="#C4552D"></path><path d="M24 32V21" stroke="#FFF8EE" stroke-width="3" stroke-linecap="round"></path><path d="M24 22c0-4.5-3-7.5-8-7.5 0 4.5 3 7.5 8 7.5zM24 25c0-4 2.6-7 7.5-7 0 4-2.6 7-7.5 7z" fill="#FFF8EE"></path></svg>`;
}

// Contenido del micrófono según su estado
function iconoMicrofono(estado, s) {
  if (estado === 'processing') return `<svg class="spin" viewBox="0 0 24 24" width="${s}" height="${s}" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M12 3a9 9 0 1 1-9 9"></path></svg>`;
  if (estado === 'done') return `<svg viewBox="0 0 24 24" width="${s}" height="${s}" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4.5 12.5l5 5L19.5 7"></path></svg>`;
  return `<svg viewBox="0 0 24 24" width="${s}" height="${s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="2.5" width="6" height="12" rx="3" fill="currentColor"></rect><path d="M5.5 10.5a6.5 6.5 0 0 0 13 0M12 17v4M8.5 21h7"></path></svg>`;
}

// Rellena los marcadores del HTML: <i data-icono="mic" data-s="28">, <i data-retrato="rosa" data-s="40">, <div data-ilustracion="amasar">, <i data-logo>
function pintarDibujos(raiz = document) {
  raiz.querySelectorAll('[data-icono]').forEach(el => { el.outerHTML = icono(el.dataset.icono, Number(el.dataset.s) || 24, Number(el.dataset.g) || 2); });
  raiz.querySelectorAll('[data-retrato]').forEach(el => { el.outerHTML = retrato(el.dataset.retrato, Number(el.dataset.s) || 120); });
  raiz.querySelectorAll('[data-ilustracion]').forEach(el => { el.innerHTML = ilustracion(el.dataset.ilustracion, el.dataset.texto || 'Pan amasado'); el.removeAttribute('data-ilustracion'); });
  raiz.querySelectorAll('[data-logo]').forEach(el => { el.outerHTML = logo(Number(el.dataset.s) || 48); });
}
